	(
	prdct_name
	,prdct_ty_cd
	,brand_id
	,mnf_country
	,wh_date
	,prdct_stat_ty_cd
	,prdct_visible_cd
	,puchas_prc
	,trde_prc
	,reg_time
	,upd_time
	,i_num
	,shop_id
	,color_id
	,color_id2
	,prdct_ty
	,mtrl_id
	,prdct_shape
	,memo
	) 
VALUES (
	#{prdctName}
	,#{prdctTyCd}
	,#{brandId}
	,#{mnfCountry}
	,#{whDate}
	,#{prdctStatTyCd}
	,#{prdctVisibleCd}
	,#{puchasPrc}
	,#{trdePrc}
	, now()
	, now()
	,#{iNum}
	,#{shopId}
	,#{colorId}
	,#{colorId2}
	,#{prdctTy}
	,#{mtrlId}
	,#{prdctShape}
	,#{memo}
	)    

