SELECT (select c_name from com_info where i_num = O.i_num)comName ,(select shop_name from shop where shop_id = O.shop_id)shopName ,cnt ,shop_id ,i_num
,puchas_prc ,(select tax from com_info where i_num = O.i_num)tax ,deliver_time ,devide ,admin_allow ,due_month ,prdct_ty FROM orderlist O WHERE state != 0 AND return_cd !=2 AND cancel != 1 AND prdct_ty = #{comTy}
AND shop_id = #{shopId}
AND i_num = #{iNum}
AND (date(deliver_time) >= date(#{sdate}) AND date(deliver_time) <= date(#{edate}) OR (devide !=0 AND admin_allow = 1 AND due_month >= substr(${sdate},6,1))) ORDER BY deliver_time DESC

select (select c_name from com_info where i_num = O.i_num)comName ,(select shop_name from shop where shop_id = O.shop_id)shopName ,ifnull(sum((select round(puchas_prc*0.1*cnt) + puchas_prc * cnt from orderlist where id = O.id and state != 0 and cancel=0)),0)sales ,ifnull(sum((select round(puchas_prc*0.1*cnt) + puchas_prc * total_rtn_cnt from orderlist where id = O.id and return_cd=2)),0)return_prc ,sum(ifnull((select round(puchas_prc*0.1*cnt) + puchas_prc * cnt from orderlist where id = O.id and state != 0 and cancel=0),0)-ifnull((select round(puchas_prc*0.1*cnt) + puchas_prc * total_rtn_cnt from orderlist where id = O.id and return_cd=2),0))pay ,devide
,sum(if(ifnull((select round(puchas_prc*0.1*cnt) + puchas_prc * cnt from orderlist where id = O.id and state != 0 and cancel=0),0) -ifnull((select round(puchas_prc*0.1*cnt) + puchas_prc * total_rtn_cnt from orderlist where id = O.id and return_cd=2),0)=0 or devide=0 ,puchas_prc*0 ,(if(devide!=0 ,round(round((puchas_prc*0.1*cnt) + (puchas_prc*cnt))/devide) ,round(round((puchas_prc*0.1*cnt) + (puchas_prc*cnt))/1))))) devide_pay
,ifnull(round(sum((select round(puchas_prc*0.1*cnt) + puchas_prc * cnt from orderlist where id = O.id and state != 0 and cancel=0))*((select tax from com_info where i_num = O.i_num)/100)),0)tax from orderlist O where (date(deliver_time) >= date(#{sdate}) AND date(deliver_time) <= date(#{edate}) OR (devide !=0 AND admin_allow = 1 AND due_month >= substr(#{sdate},6,1))) group by comName, shopName order by comName;

select (select c_name from com_info where i_num = O.i_num)comName ,(select shop_name from shop where shop_id = O.shop_id)shopName ,ifnull(sum((select round(puchas_prc*0.1*cnt) + puchas_prc * cnt from orderlist where id = O.id and state != 0 and cancel=0)),0)sales ,ifnull(sum((select round(puchas_prc*0.1*cnt) + puchas_prc * total_rtn_cnt from orderlist where id = O.id and return_cd=2)),0)return_prc ,sum(ifnull((select round(puchas_prc*0.1*cnt) + puchas_prc * cnt from orderlist where id = O.id and state != 0 and cancel=0),0)-ifnull((select round(puchas_prc*0.1*cnt) + puchas_prc * total_rtn_cnt from orderlist where id = O.id and return_cd=2),0))pay ,devide
,sum(if(ifnull((select round(puchas_prc*0.1*cnt) + puchas_prc * cnt from orderlist where id = O.id and state != 0 and cancel=0),0) -ifnull((select round(puchas_prc*0.1*cnt) + puchas_prc * total_rtn_cnt from orderlist where id = O.id and return_cd=2),0)=0 or devide=0 ,puchas_prc*0 ,(if(devide!=0 ,round(round((puchas_prc*0.1*cnt) + (puchas_prc*cnt))/devide) ,round(round((puchas_prc*0.1*cnt) + (puchas_prc*cnt))/1))))) devide_pay
from orderlist O where (date(deliver_time) >= date(#{sdate}) AND date(deliver_time) <= date(#{edate}) OR (devide !=0 AND admin_allow = 1 AND due_month >= substr(#{sdate},6,1))) group by comName, shopName order by shopName;
